INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6073, '是的，时候到了，$c。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Yes, it is time, $c.
